package com.enrollnow.identity.services;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.util.Base64;

public final class EnrollNowEmailAssets {

    public static final String LOGO_CONTENT_ID = "enrollnow-logo";
    public static final String LOGO_FILENAME = "enrollnow-logo.png";
    public static final String LOGO_CONTENT_TYPE = "image/png";

    // Embedded fallback base64 logo
    private static final String EMBEDDED_FALLBACK_BASE64 =
            "";

    private static String cachedLogoBase64;

    private EnrollNowEmailAssets() {
    }

    public static synchronized String getLogoBase64() {
        if (cachedLogoBase64 != null) {
            return cachedLogoBase64;
        }

        try (InputStream is = EnrollNowEmailAssets.class.getClassLoader().getResourceAsStream("assets/enrollnow-logo.png")) {
            if (is != null) {
                ByteArrayOutputStream buffer = new ByteArrayOutputStream();
                byte[] data = new byte[4096];
                int nRead;
                while ((nRead = is.read(data, 0, data.length)) != -1) {
                    buffer.write(data, 0, nRead);
                }
                buffer.flush();
                cachedLogoBase64 = Base64.getEncoder().encodeToString(buffer.toByteArray());
                return cachedLogoBase64;
            }
        } catch (Exception e) {
            // fallback to embedded constant
        }

        cachedLogoBase64 = EMBEDDED_FALLBACK_BASE64;
        return cachedLogoBase64;
    }
}
